SELECT b.id, 40, 'বাংলাদেশের প্রতিরক্ষা ও নিরাপত্তা বাহিনী', 'bangladesh-defence-security', 'Source-derived defence, police, border-security, and operation material with explicit verification states.', 468, 40
FROM public.books b WHERE b.title = 'Jubayer''s GK' AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.book_id = b.id AND c.slug = 'bangladesh-defence-security');
INSERT INTO public.topics (chapter_id, title, slug, description, source_page, display_order)
SELECT c.id, x.title, x.slug, x.description, x.source_page, x.display_order FROM (VALUES
 ('bangladesh-police-information', 'বাংলাদেশ পুলিশ', 'Police facts, locations, laws, and historical context.', 469, 6),
 ('armed-forces', 'বাংলাদেশের সশস্ত্র বাহিনী', 'Army, Air Force, Navy, and institutional abbreviations.', 470, 7),
 ('border-and-public-security', 'সীমান্ত ও জননিরাপত্তা বাহিনী', 'Border Guard, RAB, Coast Guard, and SSF source material.', 471, 8),
 ('ansar-and-military-terms', 'আনসার ও সামরিক পরিভাষা', 'Ansar-VDP material, academy locations, and military terminology.', 472, 9),
 ('bangladesh-operations', 'বাংলাদেশের অপারেশন', 'Named relief, security, and public-administration operations.', 473, 10)
) AS x(slug, title, description, source_page, display_order) JOIN public.chapters c ON c.slug = 'bangladesh-defence-security' AND c.book_id = (SELECT id FROM public.books WHERE title = 'Jubayer''s GK' LIMIT 1)
WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.chapter_id = c.id AND t.slug = x.slug);
INSERT INTO public.source_pages (import_run_id, book_id, source_page, page_kind, raw_transcription, chapter_heading, topic_heading, confidence, extraction_method, model_name, notes, review_metadata)
SELECT (SELECT id FROM public.import_runs WHERE pipeline_version = 'vision-quality-gated-batch-0469-0473-v1' ORDER BY started_at DESC LIMIT 1), b.id, 469, 'educational'::page_kind, 'বাংলাদেশ পুলিশ সম্পর্কে আরো কিছু তথ্য ♦ দেশের প্রথম নারী ওসি- ইন্সপেক্টর হোসনে আরা বেগম। ♦ বাংলাদেশ পুলিশ ইন্টারপোলের সদস্য হয়- ১৯৭৬ সালে। ♦ পুলিশের প্রশাসনিক অঞ্চলগুলো হলো- রেঞ্জ, সার্কেল, জেলা ও থানা। ♦ বর্তমানে মেট্রোপলিটন এলাকা রয়েছে- ৮টি। ♦ পুলিশ বাহিনীতে প্রথম নারী সদস্য নিয়োগ দেওয়া হয়- ১৯৭৪ সালে। ♦ বাংলাদেশ পুলিশ একাডেমি অবস্থিত- সারদা, রাজশাহী। ♦ রাস্তায় ট্রাফিক সিগন্যালের লাইট যে ক্রম অনুসারে জ্বলে- লাল-হলুদ-সবুজ-হলুদ-লাল। পুলিশ একাডেমি সারদা, রাজশাহী পুলিশ স্টাফ কলেজ মিরপুর, ঢাকা পুলিশ সদর দপ্তর ফুলবাড়িয়া, ঢাকা তাহলে রাজারবাগ কী? রাজারবাগে মূলত ঢাকা মেট্রোপলিটন পুলিশ (ডিএমপি) এর মূল ব্যারাক অবস্থিত। এটি রাজারবাগ পুলিশ লাইনস নামে পরিচিত। ১৯৭১ সালের ২৫ মার্চ কালরাতে পাকিস্তানি হানাদার বাহিনী যখন ঢাকায় ‘অপারেশন সার্চলাইট’ নামে গণহত্যা শুরু করে, তখন রাজারবাগ পুলিশ লাইনস থেকেই আধুনিক অস্ত্রের বিরুদ্ধে থ্রি নট থ্রি রাইফেল নিয়ে প্রথম প্রতিরোধ গড়ে তোলা হয়েছিল। বহুল ব্যবহৃত পুলিশের তিন আইন ধারা-৫৪ ধারা-১৪৪ ধারা-৪২০ বিনা ওয়ারেন্টে পুলিশ কর্তৃক গ্রেপ্তার করার ক্ষমতা। মানুষের চলাচল, আচরণ এবং কর্মকাণ্ডের বিধি-নিষেধ বা নিয়ন্ত্রণ। বাংলাদেশ Penal Code এর একটি ধারা যেখানে প্রতারণার জন্য দন্ডের বিধান রাখা হয়েছে। Zubair''s GK - 412', 'বাংলাদেশের প্রতিরক্ষা ও নিরাপত্তা বাহিনী', 'বাংলাদেশ পুলিশ', 'high'::confidence_level, 'vision_ocr_with_image_grounded_review', 'gemini-3-flash-preview', 'Quality-gated batch with correction log, content-type separation, visual review, and external-verification ledger.', '{"source_image_sha256":"595115ac587cd6acd7b4b9c62f6f542aeb17f1b3ec9f0d91d260ccb23cb2af1c","extraction_model":"gemini-3-flash-preview","review_status":"accepted_with_flags","corrections":[{"transcribed_text":"বন্দোবস্তর","source_reading":"দন্ডের","reason":"Misreading of the word ''দন্ডের'' (punishment) as ''বন্দোবস্তর'' (arrangement) in the section describing Section 420."},{"transcribed_text":"৪১২","source_reading":"412","reason":"Digit script mismatch; the source footer uses English digits."}],"unresolved_spans":[],"accepted_content_tags":["topic_heading","fact","table","exam_metadata","definition"],"physical_source_page":469,"printed_book_page":412,"nested_artifact_page_number":469,"page_number_mismatch":null,"visual_review_report":null,"external_verification_report":"/home/ubuntu/dontonyo/reports/batch-0469-0473_external_verification.md","page_kind":"educational"}'::jsonb FROM public.books b WHERE b.title = 'Jubayer''s GK' AND NOT EXISTS (SELECT 1 FROM public.source_pages s WHERE s.book_id = b.id AND s.source_page = 469);
