('472', 'bangladesh-defence-security', 'ansar-and-military-terms', 'সামরিক পরিভাষা', 'প্রক্সি যুদ্ধ: অন্য পক্ষের হয়ে যুদ্ধ করা। ক্যাজুয়ালটি: যুদ্ধে নিহত, আহত বা নিখোঁজ সদস্য। পরাশক্তি: পরাশক্তি হলো যে সমস্ত দেশ সামরিক শক্তির বিচারে অসীম ক্ষমতার অধিকারী। আধা-সামরিক বাহিনী: সামরিক বাহিনীর মতো প্রশিক্ষণ কার্যপদ্ধতি থাকলেও এটি আইনভাবে দেশের সামরিক বাহিনীর অংশ নয়। অপারেশন: নির্দিষ্ট লক্ষ্যবস্তু অর্জনের জন্য সশস্ত্র বাহিনী কর্তৃক পরিচালিত, সুনির্দিষ্ট সামরিক পদক্ষেপ। সামরিক ঘাঁটি: যেখানে কোন দেশের সশস্ত্র বাহিনী অবস্থান করে, প্রশিক্ষণ নেয় ও সামরিক কার্যক্রম পরিচালনা করে।', 'medium', '06b470ccc8bb3a160f492b17c7560c174254196d11f16d0cd0e949573e2026a5'),
('473', 'bangladesh-defence-security', 'bangladesh-operations', 'বাংলাদেশের অপারেশন', 'অপারেশন সি অ্যাঞ্জেল: ১৯৯১ সালের ভয়াবহ ঘূর্ণিঝড়ের সময় মার্কিন সেনাবাহিনী পরিচালিত ত্রাণ কার্যক্রমের সাংকেতিক নাম।
অপারেশন ক্লিনহার্ট: ২০০২, ২০০৩ সালে বাংলাদেশের সন্ত্রাস দমন এবং অবৈধ অস্ত্র উদ্ধারের জন্য যৌথ বাহিনীর পরিচালিত অভিযান।
অপারেশন নবযাত্রা: ২০০৭ সালে দেশব্যাপী ছবিসহ ভোটার তালিকা ও জাতীয় পরিচয়পত্র প্রণয়ন কর্মসূচি।
অপারেশন ডালভাত: নিত্যপ্রয়োজনীয় দ্রব্যসামগ্রীর মূল্য সহনীয় পর্যায়ে রাখতে বাংলাদেশ রাইফেলস কর্তৃক ন্যায্যমূল্যে ও সঠিক ওজনে খোলা বাজারে পণ্য বিক্রির কর্মসূচি।
অপারেশন রেবল হান্ট: ২০০৯ সালে বিডিআর সদর দপ্তর পিলখানা হত্যাযজ্ঞের সাথে জড়িত পলাতক বিডিআর সদস্যদের গ্রেফতার করতে দেশব্যাপী সেনাবাহিনী পরিচালিত অভিযান।
অপারেশন সি অ্যাঞ্জেল-২: ২০০৭ সালে ভয়াবহ ঘূর্ণিঝড় সিডরের সময় মার্কিন সেনাবাহিনী পরিচালিত ত্রাণ কার্যক্রমের সাংকেতিক নাম।
অপারেশন থান্ডার বোল্ট: ২০১৬ সালের ১-২ জুলাই গুলশানের হলি আর্টিজেন বেকারীতে জঙ্গিদমন অভিযান।
অপারেশন ডেভিল হান্ট: ২০১৫-এ শুরু হওয়া একটি বিশেষ যৌথ অভিযান, যা মূলত সন্ত্রাসবাদ দমন, সহিংসতা হ্রাস এবং আইন-শৃঙ্খলা পরিস্থিতির উন্নতির লক্ষ্যে পরিচালিত।', 'medium', 'b1f679d4be86418efb2f9ca862a746818e4e45316ab28e38418da284be1a81c2'))
INSERT INTO public.gk_notes (book_id, chapter_id, topic_id, title, content, source_page, source_section, display_order, confidence, canonical_hash)
SELECT b.id, c.id, t.id, d.title, d.content, d.source_page::integer, d.title, d.source_page::integer, d.confidence::confidence_level, d.canonical_hash FROM data d JOIN public.books b ON b.title = 'Jubayer''s GK' JOIN public.chapters c ON c.book_id = b.id AND c.slug = d.chapter_slug JOIN public.topics t ON t.chapter_id = c.id AND t.slug = d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET content = EXCLUDED.content, confidence = EXCLUDED.confidence;
INSERT INTO public.content_tags (slug, label, category, description) VALUES
('bangladesh-defence', 'Bangladesh defence', 'domain', 'Bangladesh armed forces, security institutions, and military terminology.'),
('bangladesh-police', 'Bangladesh Police', 'domain', 'Police organisation, law references, and policing history.'),
('border-security', 'Border and public security', 'domain', 'Border Guard, RAB, Coast Guard, SSF, Ansar, and public-security material.'),
('bangladesh-operations', 'Bangladesh operations', 'content_type', 'Named security, relief, and public-administration operations.'),
('biography', 'Biography', 'content_type', 'Named-person biographical source material.'),
('table', 'Table or reference list', 'content_type', 'Source table, structured list, or labelled reference information.'),
('definition', 'Definition', 'content_type', 'Definition or terminology preserved from the source.'),
('location-reference', 'Location reference', 'content_type', 'Institution location preserved as a separate study note.'),
('source-attributed', 'Source-attributed', 'quality', 'Preserved from the book with source linkage but no completed independent verification.'),
('externally-verified', 'Externally verified', 'quality', 'Corroborated by an external source listed in the verification ledger.'),
('conflicting-verification', 'Conflicting verification', 'quality', 'External evidence conflicts with the book''s exact claim or printed answer.')
ON CONFLICT (slug) DO UPDATE SET label = EXCLUDED.label, category = EXCLUDED.category, description = EXCLUDED.description;
