INSERT INTO public.fact_verifications (source_page, entity_type, entity_id, claim_text, normalized_claim, verification_status, confidence, verification_sources, audit_note) SELECT 469, 'fact', (SELECT id FROM public.gk_facts WHERE canonical_hash = '7b5437c7e56b888d10dca7c532ad7e2b83df62695474637db7bf13550480000c' LIMIT 1), 'রাজারবাগে মূলত ঢাকা মেট্রোপলিটন পুলিশ (ডিএমপি) এর মূল ব্যারাক অবস্থিত। এটি রাজারবাগ পুলিশ লাইনস নামে পরিচিত। ১৯৭১ সালের ২৫ মার্চ কালরাতে পাকিস্তানি হানাদার বাহিনী যখন ঢাকায় ‘অপারেশন সার্চলাইট’ নামে গণহত্যা শুরু করে, তখন রাজারবাগ পুলিশ লাইনস থেকেই আধুনিক অস্ত্রের বিরুদ্ধে থ্রি নট থ্রি রাইফেল নিয়ে প্রথম প্রতিরোধ গড়ে তোলা হয়েছিল।', 'রাজারবাগে মূলত ঢাকা মেট্রোপলিটন পুলিশ (ডিএমপি) এর মূল ব্যারাক অবস্থিত। এটি রাজারবাগ পুলিশ লাইনস নামে পরিচিত। ১৯৭১ সালের ২৫ মার্চ কালরাতে পাকিস্তানি হানাদার বাহিনী যখন ঢাকায় ‘অপারেশন সার্চলাইট’ নামে গণহত্যা শুরু করে, তখন রাজারবাগ পুলিশ লাইনস থেকেই আধুনিক অস্ত্রের বিরুদ্ধে থ্রি নট থ্রি রাইফেল নিয়ে প্রথম প্রতিরোধ গড়ে তোলা হয়েছিল।', 'source_attributed', 'medium'::confidence_level, '[]'::jsonb, 'Retained as source-attributed material pending deeper verification.' WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type = 'fact' AND v.entity_id = (SELECT id FROM public.gk_facts WHERE canonical_hash = '7b5437c7e56b888d10dca7c532ad7e2b83df62695474637db7bf13550480000c' LIMIT 1) AND v.claim_text = 'রাজারবাগে মূলত ঢাকা মেট্রোপলিটন পুলিশ (ডিএমপি) এর মূল ব্যারাক অবস্থিত। এটি রাজারবাগ পুলিশ লাইনস নামে পরিচিত। ১৯৭১ সালের ২৫ মার্চ কালরাতে পাকিস্তানি হানাদার বাহিনী যখন ঢাকায় ‘অপারেশন সার্চলাইট’ নামে গণহত্যা শুরু করে, তখন রাজারবাগ পুলিশ লাইনস থেকেই আধুনিক অস্ত্রের বিরুদ্ধে থ্রি নট থ্রি রাইফেল নিয়ে প্রথম প্রতিরোধ গড়ে তোলা হয়েছিল।');
INSERT INTO public.fact_verifications (source_page, entity_type, entity_id, claim_text, normalized_claim, verification_status, confidence, verification_sources, audit_note) SELECT 470, 'fact', (SELECT id FROM public.gk_facts WHERE canonical_hash = 'fe1c784743bcfb5d031ec2e419ba97c77b4074645e6b215826ddb6e161b0883a' LIMIT 1), 'এম এ জি ওসমানী
