INSERT INTO public.fact_verifications (source_page, entity_type, entity_id, claim_text, normalized_claim, verification_status, confidence, verification_sources, audit_note) SELECT 471, 'fact', (SELECT id FROM public.gk_facts WHERE canonical_hash = '12a1130a95aa067097197c96b0817e98b38ef3a24fd95f2a301bfcdc538750c7' LIMIT 1), 'বর্ডার গার্ড বাংলাদেশ (বিজিবি) হলো বাংলাদেশের প্রধান আধা-সামরিক সীমান্তরক্ষী বাহিনী, যা স্বরাষ্ট্র মন্ত্রণালয়ের অধীনে পরিচালিত হয়। ১৭৯৫ সালে পার্বত্য চট্টগ্রামে ''রামগড় লোকাল ব্যাটালিয়ন'' হিসেবে এই বাহিনীর যাত্রা শুরু হয়। দীর্ঘদিন বাংলাদেশ রাইফেলস (বিডিআর) নামে পরিচিত থাকলেও, ২০০৯ সালের পিলখানা বিদ্রোহের পর এর নাম পরিবর্তন করে বর্ডার গার্ড বাংলাদেশ (বিজিবি) রাখা হয়। ২০১০ সালের ৮ ডিসেম্বর জাতীয় সংসদে বিল পাস হয়ে ২০১১ সালের ২৩ জানুয়ারি থেকে আনুষ্ঠানিকভাবে বিজিবি নামে এই বাহিনীর নতুন করে পথচলা শুরু হয়।', 'বর্ডার গার্ড বাংলাদেশ (বিজিবি) হলো বাংলাদেশের প্রধান আধা-সামরিক সীমান্তরক্ষী বাহিনী, যা স্বরাষ্ট্র মন্ত্রণালয়ের অধীনে পরিচালিত হয়। ১৭৯৫ সালে পার্বত্য চট্টগ্রামে ''রামগড় লোকাল ব্যাটালিয়ন'' হিসেবে এই বাহিনীর যাত্রা শুরু হয়। দীর্ঘদিন বাংলাদেশ রাইফেলস (বিডিআর) নামে পরিচিত থাকলেও, ২০০৯ সালের পিলখানা বিদ্রোহের পর এর নাম পরিবর্তন করে বর্ডার গার্ড বাংলাদেশ (বিজিবি) রাখা হয়। ২০১০ সালের ৮ ডিসেম্বর জাতীয় সংসদে বিল পাস হয়ে ২০১১ সালের ২৩ জানুয়ারি থেকে আনুষ্ঠানিকভাবে বিজিবি নামে এই বাহিনীর নতুন করে পথচলা শুরু হয়।', 'source_attributed', 'medium'::confidence_level, '[]'::jsonb, 'Retained as source-attributed material pending deeper verification.' WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type = 'fact' AND v.entity_id = (SELECT id FROM public.gk_facts WHERE canonical_hash = '12a1130a95aa067097197c96b0817e98b38ef3a24fd95f2a301bfcdc538750c7' LIMIT 1) AND v.claim_text = 'বর্ডার গার্ড বাংলাদেশ (বিজিবি) হলো বাংলাদেশের প্রধান আধা-সামরিক সীমান্তরক্ষী বাহিনী, যা স্বরাষ্ট্র মন্ত্রণালয়ের অধীনে পরিচালিত হয়। ১৭৯৫ সালে পার্বত্য চট্টগ্রামে ''রামগড় লোকাল ব্যাটালিয়ন'' হিসেবে এই বাহিনীর যাত্রা শুরু হয়। দীর্ঘদিন বাংলাদেশ রাইফেলস (বিডিআর) নামে পরিচিত থাকলেও, ২০০৯ সালের পিলখানা বিদ্রোহের পর এর নাম পরিবর্তন করে বর্ডার গার্ড বাংলাদেশ (বিজিবি) রাখা হয়। ২০১০ সালের ৮ ডিসেম্বর জাতীয় সংসদে বিল পাস হয়ে ২০১১ সালের ২৩ জানুয়ারি থেকে আনুষ্ঠানিকভাবে বিজিবি নামে এই বাহিনীর নতুন করে পথচলা শুরু হয়।');
