INSERT INTO public.fact_verifications (source_page, entity_type, entity_id, claim_text, normalized_claim, verification_status, confidence, verification_sources, audit_note) SELECT 472, 'note', (SELECT id FROM public.gk_notes WHERE canonical_hash = '06b470ccc8bb3a160f492b17c7560c174254196d11f16d0cd0e949573e2026a5' LIMIT 1), 'প্রক্সি যুদ্ধ: অন্য পক্ষের হয়ে যুদ্ধ করা। ক্যাজুয়ালটি: যুদ্ধে নিহত, আহত বা নিখোঁজ সদস্য। পরাশক্তি: পরাশক্তি হলো যে সমস্ত দেশ সামরিক শক্তির বিচারে অসীম ক্ষমতার অধিকারী। আধা-সামরিক বাহিনী: সামরিক বাহিনীর মতো প্রশিক্ষণ কার্যপদ্ধতি থাকলেও এটি আইনভাবে দেশের সামরিক বাহিনীর অংশ নয়। অপারেশন: নির্দিষ্ট লক্ষ্যবস্তু অর্জনের জন্য সশস্ত্র বাহিনী কর্তৃক পরিচালিত, সুনির্দিষ্ট সামরিক পদক্ষেপ। সামরিক ঘাঁটি: যেখানে কোন দেশের সশস্ত্র বাহিনী অবস্থান করে, প্রশিক্ষণ নেয় ও সামরিক কার্যক্রম পরিচালনা করে।', 'প্রক্সি যুদ্ধ: অন্য পক্ষের হয়ে যুদ্ধ করা। ক্যাজুয়ালটি: যুদ্ধে নিহত, আহত বা নিখোঁজ সদস্য। পরাশক্তি: পরাশক্তি হলো যে সমস্ত দেশ সামরিক শক্তির বিচারে অসীম ক্ষমতার অধিকারী। আধা-সামরিক বাহিনী: সামরিক বাহিনীর মতো প্রশিক্ষণ কার্যপদ্ধতি থাকলেও এটি আইনভাবে দেশের সামরিক বাহিনীর অংশ নয়। অপারেশন: নির্দিষ্ট লক্ষ্যবস্তু অর্জনের জন্য সশস্ত্র বাহিনী কর্তৃক পরিচালিত, সুনির্দিষ্ট সামরিক পদক্ষেপ। সামরিক ঘাঁটি: যেখানে কোন দেশের সশস্ত্র বাহিনী অবস্থান করে, প্রশিক্ষণ নেয় ও সামরিক কার্যক্রম পরিচালনা করে।', 'source_attributed', 'medium'::confidence_level, '[]'::jsonb, 'Retained as source-attributed material pending deeper verification.' WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type = 'note' AND v.entity_id = (SELECT id FROM public.gk_notes WHERE canonical_hash = '06b470ccc8bb3a160f492b17c7560c174254196d11f16d0cd0e949573e2026a5' LIMIT 1) AND v.claim_text = 'প্রক্সি যুদ্ধ: অন্য পক্ষের হয়ে যুদ্ধ করা। ক্যাজুয়ালটি: যুদ্ধে নিহত, আহত বা নিখোঁজ সদস্য। পরাশক্তি: পরাশক্তি হলো যে সমস্ত দেশ সামরিক শক্তির বিচারে অসীম ক্ষমতার অধিকারী। আধা-সামরিক বাহিনী: সামরিক বাহিনীর মতো প্রশিক্ষণ কার্যপদ্ধতি থাকলেও এটি আইনভাবে দেশের সামরিক বাহিনীর অংশ নয়। অপারেশন: নির্দিষ্ট লক্ষ্যবস্তু 