INSERT INTO public.fact_verifications (source_page, entity_type, entity_id, claim_text, normalized_claim, verification_status, confidence, verification_sources, audit_note) SELECT 473, 'note', (SELECT id FROM public.gk_notes WHERE canonical_hash = 'b1f679d4be86418efb2f9ca862a746818e4e45316ab28e38418da284be1a81c2' LIMIT 1), 'অপারেশন সি অ্যাঞ্জেল: ১৯৯১ সালের ভয়াবহ ঘূর্ণিঝড়ের সময় মার্কিন সেনাবাহিনী পরিচালিত ত্রাণ কার্যক্রমের সাংকেতিক নাম।
অপারেশন ক্লিনহার্ট: ২০০২, ২০০৩ সালে বাংলাদেশের সন্ত্রাস দমন এবং অবৈধ অস্ত্র উদ্ধারের জন্য যৌথ বাহিনীর পরিচালিত অভিযান।
অপারেশন নবযাত্রা: ২০০৭ সালে দেশব্যাপী ছবিসহ ভোটার তালিকা ও জাতীয় পরিচয়পত্র প্রণয়ন কর্মসূচি।
অপারেশন ডালভাত: নিত্যপ্রয়োজনীয় দ্রব্যসামগ্রীর মূল্য সহনীয় পর্যায়ে রাখতে বাংলাদেশ রাইফেলস কর্তৃক ন্যায্যমূল্যে ও সঠিক ওজনে খোলা বাজারে পণ্য বিক্রির কর্মসূচি।
অপারেশন রেবল হান্ট: ২০০৯ সালে বিডিআর সদর দপ্তর পিলখানা হত্যাযজ্ঞের সাথে জড়িত পলাতক বিডিআর সদস্যদের গ্রেফতার করতে দেশব্যাপী সেনাবাহিনী পরিচালিত অভিযান।
অপারেশন সি অ্যাঞ্জেল-২: ২০০৭ সালে ভয়াবহ ঘূর্ণিঝড় সিডরের সময় মার্কিন সেনাবাহিনী পরিচালিত ত্রাণ কার্যক্রমের সাংকেতিক নাম।
অপারেশন থান্ডার বোল্ট: ২০১৬ সালের ১-২ জুলাই গুলশানের হলি আর্টিজেন বেকারীতে জঙ্গিদমন অভিযান।
অপারেশন ডেভিল হান্ট: ২০১৫-এ শুরু হওয়া একটি বিশেষ যৌথ অভিযান, যা মূলত সন্ত্রাসবাদ দমন, সহিংসতা হ্রাস এবং আইন-শৃঙ্খলা পরিস্থিতির উন্নতির লক্ষ্যে পরিচালিত।', 'অপারেশন সি অ্যাঞ্জেল: ১৯৯১ সালের ভয়াবহ ঘূর্ণিঝড়ের সময় মার্কিন সেনাবাহিনী পরিচালিত ত্রাণ কার্যক্রমের সাংকেতিক নাম।
